insert into public.deployment_check (check_key, section, title, why, kind, severity, expected, status, value, detail, last_run_at, active, sort_order)
values
 ('ops.sync_button_regression', '6 Defects', 'Owner reports the Sync button no longer works after today''s changes — find, fix, revert what broke it', 'Measured 21:05 UTC: the scheduled syncs are healthy (932 ok runs today, last 21:00 UTC; sheet-sync 2 ok; Apex 815 runs). metrc-sync v29 (GPT, 11 Sep) refuses a delta whose cursor key is missing — all 10 cursor keys are present. Today''s front-end diff (Grok: bots panel, Settings desk, Bots paid key, brand locker, Budz) does not touch the Sync all / Sync buttons in App.jsx or syncitems.jsx. NOTE: Claude''s own HR menu change (20:58 UTC) briefly removed the HR pages from the live menu and added a button the live build could not open; reverted 21:05 UTC. Needs: which page and button, and what the screen shows, to pin the cause. Lane: Claude (diagnosis); the owning lane fixes.', 'manual', 'NO-GO', 'the named Sync button runs and reports', 'PENDING', 'backend healthy; front end to be pinned', null, now(), true, 61),
 ('ops.deleted_pages_after_hr', '6 Defects', 'Pages the owner reports deleted today are restored — after the HR platform work', 'Owner 12 Sep: "deleted pages we deal with after we finish HR". No file was deleted in app/web on main today and no nav_registry row was deleted; Claude''s HR menu change disabled 64 HR rows for 7 minutes and restored them. The owner names the pages; each is measured (row enabled? component mounted? route resolves?) and restored. Lane: Claude.', 'manual', 'WATCH', 'every named page opens', 'PENDING', null, null, null, true, 62),
 ('hrp.dashboard_tiles_match', '18 HR platform', 'OS HR dashboard, Control Tower and CEO dashboard show the HR platform''s own tiles — same labels, same numbers, each button opens the matching HR screen', 'Owner 12 Sep: "I want all buttons to match our HR platform." One view in the OS (public.v_hr_dashboard) computes exactly the HR platform Dashboard''s KPI set from hr.* — Active Headcount, Clocked In Now, Coverage Rate, Callouts Today, NCNS Today, Total Hours This Wk, OT Hours, OT Employees, Avg Hrs/Employee, Training Compliance, Docs Pending Ack, Open Incidents, Pending PTO — so the two never disagree. Each OS tile carries the HR platform''s label and deep-links to its route (/hr/command-center, /hr/coverage-monitor, /hr/callout, /hr/time-off-board, /hr/training, /hr/doc-center, /hr/incidents-board). Lane: Claude (view + tiles); HR platform screens unchanged.', 'manual', 'NO-GO', '13 tiles, identical values on both sides, each opens its HR screen', 'PENDING', null, null, null, true, 191)
